import{_ as n,a0 as d,w as r,s as p,ao as o,I as s,x as l,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Tlog：录制/播放终端 IO 和会话的工具 | LCTT x X-CMD","titleTemplate":false,"description":"Tlog：录制/播放终端 IO 和会话的工具 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Tlog：录制/播放终端 IO 和会话的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Tlog：录制/播放终端 IO 和会话的工具 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180104 Tlog - A Tool to Record - Play Terminal IO and Sessions","title":"Tlog：录制/播放终端 IO 和会话的工具","tag":"201803","desc":""},"relativePath":"201803/20180104 Tlog - A Tool to Record - Play Terminal IO and Sessions.md","filePath":"[post].md"}'),g={name:"201803/20180104 Tlog - A Tool to Record - Play Terminal IO and Sessions.md"};function h(u,e,c,k,b,f){const t=d("Link");return r(),p("div",null,[e[19]||(e[19]=o('<h1 id="tlog-录制-播放终端-io-和会话的工具" tabindex="-1">Tlog：录制/播放终端 IO 和会话的工具 <a class="header-anchor" href="#tlog-录制-播放终端-io-和会话的工具" aria-label="Permalink to “Tlog：录制/播放终端 IO 和会话的工具”">​</a></h1><p>Tlog 是 Linux 中终端 I/O 录制和回放软件包。它用于实现一个集中式用户会话录制。它将所有经过的消息录制为 JSON 消息。录制为 JSON 格式的主要目的是将数据传送到 ElasticSearch 之类的存储服务，可以从中搜索和查询，以及回放。同时，它们保留所有通过的数据和时序。</p><p>Tlog 包含三个工具，分别是 <code>tlog-rec</code>、tlog-rec-session<code>和</code>tlog-play`。</p><ul><li><code>tlog-rec</code> 工具一般用于录制终端、程序或 shell 的输入或输出。</li><li><code>tlog-rec-session</code> 工具用于录制整个终端会话的 I/O，包括录制的用户。</li><li><code>tlog-play</code> 工具用于回放录制。</li></ul><p>在本文中，我将解释如何在 CentOS 7.4 服务器上安装 Tlog。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>在安装之前，我们需要确保我们的系统满足编译和安装程序的所有软件要求。在第一步中，使用以下命令更新系统仓库和软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum update</span></span></code></pre></div><p>我们需要安装此软件安装所需的依赖项。在安装之前，我已经使用这些命令安装了所有依赖包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install wget gcc</span></span>\n<span class="line"><span># yum install systemd-devel json-c-devel libcurl-devel m4</span></span></code></pre></div>',10)),s("p",null,[e[1]||(e[1]=l("完成这些安装后，我们可以下载该工具的",-1)),a(t,{href:"https://github.com/Scribery/tlog/releases/download/v3/tlog-3.tar.gz"},{default:i(()=>[...e[0]||(e[0]=[l("源码包",-1)])]),_:1}),e[2]||(e[2]=l("并根据需要将其解压到服务器上：",-1))]),e[20]||(e[20]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wget https://github.com/Scribery/tlog/releases/download/v3/tlog-3.tar.gz</span></span>
<span class="line"><span># tar -xvf tlog-3.tar.gz</span></span>
<span class="line"><span># cd tlog-3</span></span></code></pre></div><p>现在，你可以使用我们通常的配置和编译方法开始构建此工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ./configure --prefix=/usr --sysconfdir=/etc &amp;&amp; make</span></span>
<span class="line"><span># make install</span></span>
<span class="line"><span># ldconfig</span></span></code></pre></div><p>最后，你需要运行 <code>ldconfig</code>。它对命令行中指定目录、<code>/etc/ld.so.conf</code> 文件，以及信任的目录（ <code>/lib</code> 和 <code>/usr/lib</code>）中最近的共享库创建必要的链接和缓存。</p><h3 id="tlog-工作流程图" tabindex="-1">Tlog 工作流程图 <a class="header-anchor" href="#tlog-工作流程图" aria-label="Permalink to “Tlog 工作流程图”">​</a></h3><p><img src="https://linoxide.com/wp-content/uploads/2018/01/Tlog-working-process.png" alt="Tlog working process"></p><p>首先，用户通过 PAM 进行身份验证登录。名称服务交换器（NSS）提供的 <code>tlog</code> 信息是用户的 shell。这初始化了 tlog 部分，并从环境变量/配置文件收集关于实际 shell 的信息，并在 PTY 中启动实际的 shell。然后通过 syslog 或 sd-journal 开始录制在终端和 PTY 之间传递的所有内容。</p><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>你可以使用 <code>tlog-rec</code> 录制一个会话并使用 <code>tlog-play</code> 回放它，以测试新安装的 tlog 是否能够正常录制和回放会话。</p><h4 id="录制到文件中" tabindex="-1">录制到文件中 <a class="header-anchor" href="#录制到文件中" aria-label="Permalink to “录制到文件中”">​</a></h4><p>要将会话录制到文件中，请在命令行中执行 <code>tlog-rec</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tlog-rec --writer=file --file-path=tlog.log</span></span></code></pre></div><p>该命令会将我们的终端会话录制到名为 <code>tlog.log</code> 的文件中，并将其保存在命令中指定的路径中。</p><h4 id="从文件中回放" tabindex="-1">从文件中回放 <a class="header-anchor" href="#从文件中回放" aria-label="Permalink to “从文件中回放”">​</a></h4><p>你可以在录制过程中或录制后使用 <code>tlog-play</code> 命令回放录制的会话。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tlog-play --reader=file --file-path=tlog.log</span></span></code></pre></div><p>该命令从指定的路径读取先前录制的文件 <code>tlog.log</code>。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,18)),s("p",null,[e[4]||(e[4]=l("Tlog 是一个开源软件包，可用于实现集中式用户会话录制。它主要是作为一个更大的用户会话录制解决方案的一部分使用，但它被设计为独立且可重用的。该工具可以帮助录制用户所做的一切，并将其存储在服务器的某个位置，以备将来参考。你可以从这个",-1)),a(t,{href:"https://github.com/Scribery/tlog/blob/master/README.md"},{default:i(()=>[...e[3]||(e[3]=[l("文档",-1)])]),_:1}),e[5]||(e[5]=l("中获得关于这个软件包使用的更多细节。我希望这篇文章对你有用。请发表你的宝贵建议和意见。",-1))]),e[21]||(e[21]=s("p",null,[s("strong",null,"关于 Saheetha Shameer （作者）")],-1)),e[22]||(e[22]=s("p",null,"我正在担任高级系统管理员。我是一名快速学习者，有轻微的倾向跟随行业中目前和正在出现的趋势。我的爱好包括听音乐、玩策略游戏、阅读和园艺。我对尝试各种美食也有很高的热情 😃",-1)),e[23]||(e[23]=s("hr",null,null,-1)),s("p",null,[e[7]||(e[7]=l("via: ",-1)),a(t,{href:"https://linoxide.com/linux-how-to/tlog-tool-record-play-terminal-io-sessions/"},{default:i(()=>[...e[6]||(e[6]=[l("https://linoxide.com/linux-how-to/tlog-tool-record-play-terminal-io-sessions/",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=l("作者：",-1)),a(t,{href:"https://linoxide.com/author/saheethas/"},{default:i(()=>[...e[8]||(e[8]=[l("Saheetha Shameer",-1)])]),_:1}),e[12]||(e[12]=l(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[9]||(e[9]=[l("geekpi",-1)])]),_:1}),e[13]||(e[13]=l(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[10]||(e[10]=[l("wxy",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=l("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[14]||(e[14]=[l("LCTT",-1)])]),_:1}),e[17]||(e[17]=l(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[15]||(e[15]=[l("Linux中国",-1)])]),_:1}),e[18]||(e[18]=l(" 荣誉推出",-1))])])}const x=n(g,[["render",h]]);export{y as __pageData,x as default};
